import com.ibm.wala.ipa.callgraph.AnalysisCacheImpl;
import com.ibm.wala.ipa.callgraph.AnalysisOptions;
import com.ibm.wala.ipa.callgraph.AnalysisOptions.ReflectionOptions;
import com.ibm.wala.ipa.callgraph.AnalysisScope;
import com.ibm.wala.ipa.callgraph.CallGraph;
import com.ibm.wala.ipa.callgraph.CallGraphBuilder;
import com.ibm.wala.ipa.callgraph.CallGraphBuilderCancelException;
import com.ibm.wala.ipa.callgraph.CallGraphStats;
import com.ibm.wala.ipa.callgraph.Entrypoint;
import com.ibm.wala.ipa.callgraph.IAnalysisCacheView;
import com.ibm.wala.ipa.callgraph.impl.DefaultEntrypoint;
import com.ibm.wala.ipa.callgraph.impl.Util;
import com.ibm.wala.ipa.cha.ClassHierarchyException;
import com.ibm.wala.ipa.cha.ClassHierarchyFactory;
import com.ibm.wala.ipa.cha.IClassHierarchy;
import com.ibm.wala.types.ClassLoaderReference;
import com.ibm.wala.types.TypeReference;
import com.ibm.wala.util.collections.Iterator2Iterable;

import java.io.File;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class WalaAnalysis {

    public static void main(String[] args) throws Exception {
        long start = System.currentTimeMillis();

        String scopeFile = "/workspace/analysis/checkstyle.scope";
        File exclusionsFile = new File("/workspace/analysis/exclusions.txt");

        System.out.println("=== WALA Analysis of Checkstyle ===");
        System.out.println();

        // Read analysis scope
        AnalysisScope scope = AnalysisScopeReader.instance.readJavaScope(
                scopeFile, exclusionsFile, WalaAnalysis.class.getClassLoader());

        // Build class hierarchy
        System.out.println("Building class hierarchy...");
        IClassHierarchy cha = ClassHierarchyFactory.make(scope);
        System.out.println("Classes in hierarchy: " + cha.getNumberOfClasses());
        System.out.println("Warnings: " + Warnings.asString());
        Warnings.clear();

        // Analyze application classes
        List<IClass> appClasses = new ArrayList<>();
        int appMethodCount = 0;
        int appFieldCount = 0;
        for (IClass klass : Iterator2Iterable.of(cha.iterator())) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                appClasses.add(klass);
                try {
                    appMethodCount += klass.getDeclaredMethods().size();
                } catch (Exception e) {
                    // skip
                }
                try {
                    appFieldCount += klass.getDeclaredInstanceFields().size();
                } catch (Exception e) {
                    // skip
                }
                try {
                    appFieldCount += klass.getDeclaredStaticFields().size();
                } catch (Exception e) {
                    // skip
                }
            }
        }

        Collections.sort(appClasses, Comparator.comparing(c -> c.getName().toString()));

        System.out.println("Application classes: " + appClasses.size());
        System.out.println("Application methods: " + appMethodCount);
        System.out.println("Application fields: " + appFieldCount);
        System.out.println();

        // Write class hierarchy summary
        PrintWriter classWriter = new PrintWriter("/analysis-results/class-hierarchy.txt");
        classWriter.println("=== WALA Class Hierarchy Analysis for Checkstyle ===");
        classWriter.println("Total classes in hierarchy: " + cha.getNumberOfClasses());
        classWriter.println("Application classes: " + appClasses.size());
        classWriter.println("Application methods: " + appMethodCount);
        classWriter.println("Application fields: " + appFieldCount);
        classWriter.println();
        classWriter.println("=== Application Classes ===");
        for (IClass klass : appClasses) {
            String className = klass.getName().toString().replace('/', '.');
            classWriter.println("Class: " + className);
            classWriter.println("  Loader: " + klass.getClassLoader().getName());
            try {
                IClass superClass = klass.getSuperclass();
                if (superClass != null) {
                    classWriter.println("  Superclass: " + superClass.getName().toString().replace('/', '.'));
                }
            } catch (Exception e) {
                // skip
            }
            try {
                for (IClass iface : Iterator2Iterable.of(klass.getDirectInterfaces().iterator())) {
                    classWriter.println("  Interface: " + iface.getName().toString().replace('/', '.'));
                }
            } catch (Exception e) {
                // skip
            }
            try {
                for (IMethod m : klass.getDeclaredMethods()) {
                    classWriter.println("  Method: " + m.getName() + " " + m.getDescriptor());
                }
            } catch (Exception e) {
                // skip
            }
            classWriter.println();
        }
        classWriter.close();
        System.out.println("Class hierarchy written to /analysis-results/class-hierarchy.txt");

        // Build call graph using application entry points
        System.out.println();
        System.out.println("Building call graph...");

        // Use all public methods of application classes as entry points
        Collection<Entrypoint> entrypoints = new ArrayList<>();
        for (IClass klass : appClasses) {
            try {
                for (IMethod m : klass.getDeclaredMethods()) {
                    if (m.isPublic() && !m.isAbstract() && !m.isNative()) {
                        entrypoints.add(new DefaultEntrypoint(m, cha));
                    }
                }
            } catch (Exception e) {
                // skip
            }
        }
        System.out.println("Entry points: " + entrypoints.size());

        AnalysisOptions options = new AnalysisOptions();
        options.setEntrypoints(entrypoints);
        options.setReflectionOptions(ReflectionOptions.NONE);

        IAnalysisCacheView cache = new AnalysisCacheImpl();

        CallGraphBuilder<com.ibm.wala.ipa.callgraph.propagation.InstanceKey> builder =
                Util.makeZeroOneContainerCFABuilder(options, cache, cha);

        CallGraph cg = builder.makeCallGraph(options, null);
        long end = System.currentTimeMillis();

        System.out.println("Call graph built in " + (end - start) + "ms");
        System.out.println(CallGraphStats.getStats(cg));

        // Write call graph summary
        PrintWriter cgWriter = new PrintWriter("/analysis-results/call-graph.txt");
        cgWriter.println("=== WALA Call Graph Analysis for Checkstyle ===");
        cgWriter.println("Build time: " + (end - start) + "ms");
        cgWriter.println();
        cgWriter.println(CallGraphStats.getStats(cg));
        cgWriter.println();
        cgWriter.println("=== Call Graph Nodes and Edges ===");
        for (com.ibm.wala.ipa.callgraph.CGNode node : cg) {
            cgWriter.println("Node: " + node);
            for (com.ibm.wala.ipa.callgraph.CGNode succ : Iterator2Iterable.of(cg.getSuccNodes(node))) {
                cgWriter.println("  -> " + succ);
            }
        }
        cgWriter.close();
        System.out.println("Call graph written to /analysis-results/call-graph.txt");

        // Write summary report
        PrintWriter summaryWriter = new PrintWriter("/analysis-results/analysis-summary.txt");
        summaryWriter.println("=== WALA Analysis Summary for Checkstyle ===");
        summaryWriter.println();
        summaryWriter.println("Analysis Tool: WALA (Watson Libraries for Analysis)");
        summaryWriter.println("Target Project: checkstyle");
        summaryWriter.println("Analysis Date: " + new java.util.Date());
        summaryWriter.println();
        summaryWriter.println("=== Analysis Scope ===");
        summaryWriter.println("Scope file: " + scopeFile);
        summaryWriter.println("Total classes in hierarchy: " + cha.getNumberOfClasses());
        summaryWriter.println("Application classes: " + appClasses.size());
        summaryWriter.println("Application methods: " + appMethodCount);
        summaryWriter.println("Application fields: " + appFieldCount);
        summaryWriter.println();
        summaryWriter.println("=== Call Graph Statistics ===");
        summaryWriter.println(CallGraphStats.getStats(cg));
        summaryWriter.println();
        summaryWriter.println("=== Entry Points ===");
        summaryWriter.println("Number of entry points: " + entrypoints.size());
        summaryWriter.println();
        summaryWriter.println("=== Build Information ===");
        summaryWriter.println("Total analysis time: " + (end - start) + "ms");
        summaryWriter.println("WALA version: " + getWalaVersion());
        summaryWriter.close();
        System.out.println("Summary written to /analysis-results/analysis-summary.txt");

        System.out.println();
        System.out.println("=== Analysis Complete ===");
    }

    private static String getWalaVersion() {
        try {
            return "1.8.1-SNAPSHOT";
        } catch (Exception e) {
            return "unknown";
        }
    }
}
